import csv,numpy as np
from scipy.optimize import minimize_scalar
rows=list(csv.DictReader(open('map_pred.csv')))
y=np.array([int(r['rating']) for r in rows]);p=np.clip(np.array([float(r['p']) for r in rows]),1e-6,1-1e-6)
L=np.log(p/(1-p))
def feats(kind):
  out=[]
  for r in rows:
    ex=[int(x) for x in r['number_set'].split(',')];t=int(r['target']);n=len(ex)
    if n<2 or t in ex: out.append(0.);continue
    lo,hi=min(ex),max(ex)
    if kind=='trend': d=np.sign(ex[-1]-ex[0])
    elif kind=='laststep': d=np.sign(ex[-1]-ex[-2])
    elif kind=='trendscaled': d=(ex[-1]-ex[0])/max(hi-lo,1)
    elif kind=='up': d=1
    side=1 if t>hi else -1 if t<lo else 0
    out.append(d*side)
  return np.array(out)
def ll(m,f): q=1/(1+np.exp(-(L+m*f))); return -(y*np.log(q)+(1-y)*np.log(1-q)).sum()
base=ll(0,np.zeros(len(y)))
for k in ['trend','laststep','trendscaled','up']:
  f=feats(k); r=minimize_scalar(lambda m: ll(m,f),bounds=(-3,3),method='bounded'); print(k,r.x,base-r.fun)
"

